const listPrograms = `-- name: ListPrograms :many
SELECT p.id, p.code, p.name, p.program_type, p.status,
       p.sponsor_tenant_organization_id, p.payer_tenant_organization_id,
       lower(p.valid_period)::date AS valid_from, upper(p.valid_period)::date AS valid_to,
       p.created_at, p.row_version,
       so.display_name AS sponsor_display_name,
       po.display_name AS payer_display_name,
       (SELECT count(*) FROM benefit.plan pl
         WHERE pl.tenant_id = p.tenant_id AND pl.program_id = p.id) AS plan_count
  FROM benefit.program p
  JOIN directory.tenant_organization sto
       ON sto.tenant_id = p.tenant_id AND sto.id = p.sponsor_tenant_organization_id
  JOIN directory.organization so ON so.id = sto.organization_id
  JOIN directory.tenant_organization pto
       ON pto.tenant_id = p.tenant_id AND pto.id = p.payer_tenant_organization_id
  JOIN directory.organization po ON po.id = pto.organization_id
 WHERE p.tenant_id = $1
   AND ($2::text IS NULL OR p.status = $2::text)
   AND ($3::text IS NULL
        OR p.code ILIKE $3::text OR p.name ILIKE $3::text)
   AND ($4::timestamptz IS NULL
        OR (p.created_at, p.id) < ($4::timestamptz, $5::uuid))
 ORDER BY p.created_at DESC, p.id DESC
 LIMIT $6
`

type ListProgramsParams struct {
	TenantID        uuid.UUID
	Status          *string
	Q               *string
	CursorCreatedAt *time.Time
	CursorID        uuid.NullUUID
	PageSize        int32
}

type ListProgramsRow struct {
	ID                          uuid.UUID
	Code                        string
	Name                        string
	ProgramType                 string
	Status                      string
	SponsorTenantOrganizationID uuid.UUID
	PayerTenantOrganizationID   uuid.UUID
	ValidFrom                   pgtype.Date
	ValidTo                     pgtype.Date
	CreatedAt                   time.Time
	RowVersion                  int64
	SponsorDisplayName          string
	PayerDisplayName            string
	PlanCount                   int64
}

// Keyset pagination on (created_at DESC, id DESC); the caller asks for limit+1 rows to
// learn whether a next page exists.
func (q *Queries) ListPrograms(ctx context.Context, arg ListProgramsParams) ([]ListProgramsRow, error) {
	rows, err := q.db.Query(ctx, listPrograms,
		arg.TenantID,
		arg.Status,
		arg.Q,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListProgramsRow
	for rows.Next() {
		var i ListProgramsRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.ProgramType,
			&i.Status,
			&i.SponsorTenantOrganizationID,
			&i.PayerTenantOrganizationID,
			&i.ValidFrom,
			&i.ValidTo,
			&i.CreatedAt,
			&i.RowVersion,
			&i.SponsorDisplayName,
			&i.PayerDisplayName,
			&i.PlanCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

