const resolvePlanVersion = `-- name: ResolvePlanVersion :one
SELECT v.id, v.plan_id, v.version_no, v.status,
       lower(v.valid_period)::date AS valid_from, upper(v.valid_period)::date AS valid_to,
       v.configuration_hash, v.published_at, v.published_by, v.submitted_at, v.submitted_by,
       v.review_comment, v.retire_reason_code, v.retire_reason_text, v.notes, v.created_at,
       v.xmin::text::bigint AS row_version
  FROM benefit.plan_version v
 WHERE v.tenant_id = $1 AND v.plan_id = $2 AND v.status = 'PUBLISHED'
   AND v.valid_period @> $3::date
`

type ResolvePlanVersionParams struct {
	TenantID uuid.UUID
	PlanID   uuid.UUID
	AsOf     pgtype.Date
}

type ResolvePlanVersionRow struct {
	ID                uuid.UUID
	PlanID            uuid.UUID
	VersionNo         int32
	Status            string
	ValidFrom         pgtype.Date
	ValidTo           pgtype.Date
	ConfigurationHash []byte
	PublishedAt       *time.Time
	PublishedBy       uuid.NullUUID
	SubmittedAt       *time.Time
	SubmittedBy       uuid.NullUUID
	ReviewComment     *string
	RetireReasonCode  *string
	RetireReasonText  *string
	Notes             *string
	CreatedAt         time.Time
	RowVersion        int64
}

// The PUBLISHED version whose validity period contains the service date (lower bound
// inclusive, upper bound exclusive). The exclusion constraint guarantees at most one.
func (q *Queries) ResolvePlanVersion(ctx context.Context, arg ResolvePlanVersionParams) (ResolvePlanVersionRow, error) {
	row := q.db.QueryRow(ctx, resolvePlanVersion, arg.TenantID, arg.PlanID, arg.AsOf)
	var i ResolvePlanVersionRow
	err := row.Scan(
		&i.ID,
		&i.PlanID,
		&i.VersionNo,
		&i.Status,
		&i.ValidFrom,
		&i.ValidTo,
		&i.ConfigurationHash,
		&i.PublishedAt,
		&i.PublishedBy,
		&i.SubmittedAt,
		&i.SubmittedBy,
		&i.ReviewComment,
		&i.RetireReasonCode,
		&i.RetireReasonText,
		&i.Notes,
		&i.CreatedAt,
		&i.RowVersion,
	)
	return i, err
}

